<?php
session(); include('../include/config.php'); require_once __DIR__.'/module_bootstrap.php'; hms_module_require_roles(array('admin','doctor','perawat','rekam_medis'));
if($_SERVER['REQUEST_METHOD']==='POST'){hms_module_csrf();$pid=(int)($_POST['patient_id']??0);$visit=(int)($_POST['visit_id']??0);$adm=(int)($_POST['admission_id']??0);$type=$_POST['note_type']??'CPPT';$sub=trim($_POST['subjective']??'');$obj=trim($_POST['objective']??'');$ass=trim($_POST['assessment']??'');$plan=trim($_POST['plan']??'');$code=trim($_POST['diagnosis_code']??'');$diag=trim($_POST['diagnosis_name']??'');$action=trim($_POST['action_text']??'');$serviceId=(int)($_POST['service_id']??0);$role=hms_module_current_role();$authorType=$role==='doctor'?'DOKTER':($role==='perawat'?'PERAWAT':($role==='rekam_medis'?'REKAM_MEDIS':'ADMIN'));$aid=(int)($_SESSION['id']??0);
if($pid<=0||($visit<=0&&$adm<=0)){hms_set_flash('danger','RME harus dikaitkan dengan pasien dan minimal satu kunjungan/admission.');}
else {try{
 if($visit>0){$vr=hms_fetch_one($con,'SELECT patient_id FROM hms_patient_visits WHERE id=?','i',array($visit));if(!$vr||((int)$vr['patient_id']!==$pid))throw new RuntimeException('Kunjungan tidak sesuai dengan pasien.');}
 if($adm>0){$ar=hms_fetch_one($con,'SELECT patient_id,status FROM hms_admissions WHERE id=?','i',array($adm));if(!$ar||((int)$ar['patient_id']!==$pid))throw new RuntimeException('Admission tidak sesuai dengan pasien.');}
 if(!in_array($type,array('CPPT','SOAP','KEPERAWATAN','OBSERVASI','RESUME'),true))$type='CPPT';
 $st=mysqli_prepare($con,'INSERT INTO hms_cppt(patient_id,visit_id,admission_id,author_type,author_id,note_type,subjective,objective,assessment,plan,diagnosis_code,diagnosis_name,action_text) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');if(!$st)throw new RuntimeException('RME gagal disiapkan.');mysqli_stmt_bind_param($st,'iiisiisssssss',$pid,$visit,$adm,$authorType,$aid,$type,$sub,$obj,$ass,$plan,$code,$diag,$action);if(!mysqli_stmt_execute($st)){mysqli_stmt_close($st);throw new RuntimeException('RME gagal disimpan.');}$id=mysqli_stmt_insert_id($st);mysqli_stmt_close($st);
 hms_module_workflow_event($con,$pid,$visit?:null,$adm?:null,null,'RME_ENTRY','SELESAI','Catatan klinis '.$type.' dibuat.');hms_module_audit($con,'CREATE','RME','hms_cppt',$id,'Catatan RME/CPPT dibuat',null,array('patient_id'=>$pid,'visit_id'=>$visit,'admission_id'=>$adm,'note_type'=>$type,'diagnosis_code'=>$code));
 if($serviceId>0){$svc=hms_fetch_one($con,'SELECT * FROM hms_service_catalog WHERE id=? AND is_active=1','i',array($serviceId));if($svc){try{hms_module_post_charge($con,$pid,$visit?:null,$adm?:null,$id,null,$serviceId,$svc['service_type'],$svc['service_name'],1,(float)$svc['price']);}catch(Throwable $ce){hms_set_flash('warning','RME tersimpan, tetapi charge billing gagal: '.$ce->getMessage());}}}
 hms_set_flash('success','Catatan RME/CPPT tersimpan.');
}catch(Throwable $e){hms_set_flash('danger',$e->getMessage());}}
}
$patients=hms_fetch_all($con,'SELECT ID,PatientName FROM tblpatient ORDER BY PatientName LIMIT 500');$icds=hms_fetch_all($con,'SELECT code,description FROM hms_icd10 WHERE is_active=1 ORDER BY code LIMIT 2000');$services=hms_fetch_all($con,'SELECT id,service_name,service_type,price FROM hms_service_catalog WHERE is_active=1 ORDER BY service_name');$visits=hms_fetch_all($con,"SELECT id,registration_no,patient_id,visit_date FROM hms_patient_visits ORDER BY id DESC LIMIT 300");$admissions=hms_fetch_all($con,"SELECT id,admission_no,patient_id FROM hms_admissions WHERE status='DIRAWAT' ORDER BY id DESC LIMIT 300");$rows=hms_fetch_all($con,'SELECT c.*,p.PatientName FROM hms_cppt c LEFT JOIN tblpatient p ON p.ID=c.patient_id ORDER BY c.id DESC LIMIT 100');$role=hms_module_current_role();hms_layout_header('Rekam Medis Elektronik',$role,'operations');
?>
<div class="hms-page-title"><div><h1>Rekam Medis Elektronik (RME)</h1><div class="text-muted">CPPT, SOAP, diagnosis, tindakan dan catatan klinis.</div></div></div>
<div class="hms-card p-3 mb-4"><form method="post" class="row g-3"><?php echo hms_csrf_field(); ?><div class="col-md-3"><label class="form-label">Pasien</label><select name="patient_id" class="form-select" required><option value="">Pilih pasien</option><?php foreach($patients as $p){ ?><option value="<?php echo (int)$p['ID']; ?>"><?php echo hms_e($p['PatientName']); ?></option><?php } ?></select></div><div class="col-md-3"><label class="form-label">Kunjungan</label><select name="visit_id" class="form-select"><option value="0">Tidak dipilih</option><?php foreach($visits as $v){ ?><option value="<?php echo (int)$v['id']; ?>"><?php echo hms_e($v['registration_no'].' / '.$v['visit_date']); ?></option><?php } ?></select></div><div class="col-md-3"><label class="form-label">Admission</label><select name="admission_id" class="form-select"><option value="0">Tidak dipilih</option><?php foreach($admissions as $a){ ?><option value="<?php echo (int)$a['id']; ?>"><?php echo hms_e($a['admission_no']); ?></option><?php } ?></select></div><div class="col-md-3"><label class="form-label">Jenis catatan</label><select name="note_type" class="form-select"><option>CPPT</option><option>SOAP</option><option>KEPERAWATAN</option><option>OBSERVASI</option><option>RESUME</option></select></div><div class="col-md-12"><label class="form-label">Diagnosis ICD-10</label><div class="row g-2"><div class="col-4"><select name="diagnosis_code" class="form-select"><option value="">Pilih ICD-10</option><?php foreach($icds as $ic){ ?><option value="<?php echo hms_e($ic['code']); ?>"><?php echo hms_e($ic['code'].' - '.$ic['description']); ?></option><?php } ?></select></div><div class="col-8"><input name="diagnosis_name" class="form-control" placeholder="Nama diagnosis"></div></div></div><div class="col-md-6"><label class="form-label">Tindakan/layanan otomatis ke billing</label><select name="service_id" class="form-select"><option value="0">Tidak ditagihkan otomatis</option><?php foreach($services as $sv){ ?><option value="<?php echo (int)$sv['id']; ?>"><?php echo hms_e($sv['service_name'].' - Rp '.number_format($sv['price'],0,',','.')); ?></option><?php } ?></select></div><div class="col-md-6"><label class="form-label">Subjective / Anamnesis</label><textarea name="subjective" class="form-control" rows="3"></textarea></div><div class="col-md-6"><label class="form-label">Objective / Pemeriksaan</label><textarea name="objective" class="form-control" rows="3"></textarea></div><div class="col-md-6"><label class="form-label">Assessment</label><textarea name="assessment" class="form-control" rows="3"></textarea></div><div class="col-md-6"><label class="form-label">Plan / Rencana</label><textarea name="plan" class="form-control" rows="3"></textarea></div><div class="col-12"><label class="form-label">Tindakan / Catatan</label><textarea name="action_text" class="form-control" rows="2"></textarea></div><div class="col-12"><button class="btn btn-primary">Simpan RME</button></div></form></div>
<div class="hms-card p-3"><h2 class="h5">Riwayat CPPT</h2><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Waktu</th><th>Pasien</th><th>Jenis</th><th>Penulis</th><th>Diagnosis</th><th>Assessment</th></tr></thead><tbody><?php foreach($rows as $r){ ?><tr><td><?php echo hms_e($r['created_at']); ?></td><td><?php echo hms_e($r['PatientName']); ?></td><td><?php echo hms_e($r['note_type']); ?></td><td><?php echo hms_e($r['author_type']); ?></td><td><?php echo hms_e(trim(($r['diagnosis_code']?'['.$r['diagnosis_code'].'] ':'').$r['diagnosis_name'])); ?></td><td><?php echo hms_e($r['assessment']); ?></td></tr><?php } ?></tbody></table></div></div>
<?php hms_layout_footer(); ?>
